import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static boolean mos(String[] r, String yo, String pr, String po) {
        return r[0].equals(yo) && (r[1].equals(pr) || r[1].equals("any")) && (r[2].equals(po) || r[2].equals("*"));
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        List<String[]> qoidalar = new ArrayList<>();
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            qoidalar.add(new String[] {in.next(), in.next(), in.next(), in.next()});
        }
        int q = in.nextInt();
        int taqiqlar = 0;
        for (int i = 0; i < q; i++) {
            String yo = in.next();
            String pr = in.next();
            String po = in.next();
            String javob = "ALLOW";
            for (String[] r : qoidalar) {
                if (mos(r, yo, pr, po)) {
                    javob = r[3].equals("block") ? "DENY" : "ALLOW";
                }
            }
            if (javob.equals("DENY")) {
                taqiqlar++;
            }
            System.out.println(javob);
        }
        System.out.println("BLOCKED " + taqiqlar);
    }
}

